// Keep mobile screens awake during a call. Two mechanisms run together:
// 1. Screen Wake Lock API — primary on Android/desktop, works in foregrounded iOS Safari.
// 2. Silent looping <video> — required on iOS Safari (especially after backgrounding
//    and in standalone PWA mode), where Wake Lock release+reacquire is unreliable.
// The MP4 data URI is the silent loop NoSleep.js ships (MIT, Rich Tibbett).

export type KeepAwakeHandle = { release: () => Promise<void> };

interface WakeLockSentinelLike {
  released: boolean;
  release: () => Promise<void>;
}

interface WakeLockApi {
  request: (type: "screen") => Promise<WakeLockSentinelLike>;
}

const SILENT_MP4 =
  "data:video/mp4;base64,";

async function requestWakeLock(): Promise<WakeLockSentinelLike | null> {
  if (typeof navigator === "undefined") return null;
  const nav = navigator as Navigator & { wakeLock?: WakeLockApi };
  if (!nav.wakeLock) return null;
  try {
    return await nav.wakeLock.request("screen");
  } catch (err) {
    console.warn("[keep-awake] wakeLock.request failed", err);
    return null;
  }
}

function createSilentVideo(): HTMLVideoElement {
  const video = document.createElement("video");
  video.setAttribute("playsinline", "");
  video.setAttribute("webkit-playsinline", "");
  video.muted = true;
  video.loop = true;
  video.preload = "auto";
  video.style.position = "fixed";
  video.style.right = "0";
  video.style.bottom = "0";
  video.style.width = "1px";
  video.style.height = "1px";
  video.style.opacity = "0";
  video.style.pointerEvents = "none";
  const source = document.createElement("source");
  source.src = SILENT_MP4;
  source.type = "video/mp4";
  video.appendChild(source);
  return video;
}

export async function keepAwake(): Promise<KeepAwakeHandle> {
  if (typeof document === "undefined") {
    return { release: async () => {} };
  }

  const video = createSilentVideo();
  document.body.appendChild(video);
  void video.play().catch((err) => {
    console.warn("[keep-awake] silent video play failed", err);
  });

  let sentinel = await requestWakeLock();

  const onVisibility = async () => {
    if (document.visibilityState !== "visible") return;
    if (!sentinel || sentinel.released) {
      sentinel = await requestWakeLock();
    }
    if (video.paused) {
      void video.play().catch(() => {});
    }
  };
  document.addEventListener("visibilitychange", onVisibility);

  return {
    release: async () => {
      document.removeEventListener("visibilitychange", onVisibility);
      if (sentinel && !sentinel.released) {
        try {
          await sentinel.release();
        } catch (err) {
          console.warn("[keep-awake] sentinel.release failed", err);
        }
      }
      sentinel = null;
      try {
        video.pause();
      } catch {
        /* ignore */
      }
      video.remove();
    },
  };
}
